/**
 * Test-only webfonts for visual snapshots (Inter + JetBrains Mono, OFL
 * licensed, latin subsets). Embedded as data URIs so specs run offline and
 * render identical glyphs on every OS: system font stacks differ between
 * macOS and Linux, which would fail pixel diffs on glyph shapes alone.
 *
 * Regenerate with: query the Google Fonts css2 API for
 * family=Inter:wght@400;600 and family=JetBrains+Mono:wght@400, download
 * the latin-subset woff2 files, and base64 them below.
 */
const INTER_400 = 'data:font/woff2;base64,';
const INTER_600 = 'data:font/woff2;base64,';
const MONO_400 = 'data:font/woff2;base64,';

/**
 * Stylesheet injected into every snapshotted page: registers the test fonts
 * and points the design tokens at them. The `!important` wins over the
 * per-scheme `:root[data-scheme]` scopes so every scheme renders the same
 * glyphs. Test-only: production keeps the system stacks.
 */
export function visualTestFontCSS(): string {
    return `
    @font-face { font-family: 'VisualSans'; font-style: normal; font-weight: 400; font-display: swap; src: url(${INTER_400}) format('woff2'); }
    @font-face { font-family: 'VisualSans'; font-style: normal; font-weight: 600; font-display: swap; src: url(${INTER_600}) format('woff2'); }
    @font-face { font-family: 'VisualMono'; font-style: normal; font-weight: 400; font-display: swap; src: url(${MONO_400}) format('woff2'); }
    :root { --si-font-sans: 'VisualSans', sans-serif !important; --si-font-mono: 'VisualMono', monospace !important; }`;
}
